// ============================================================================
// Environment Install Functions
// ============================================================================

/// Install web view controller in the environment.
#[unsafe(no_mangle)]
pub extern "system" fn Java_dev_waterui_android_ffi_WatcherJni_envInstallWebViewController<
    'local,
>(
    _env: JNIEnv<'local>,
    _class: JClass<'local>,
    env_ptr: jlong,
) {
    let env_ptr = require_env_ptr(env_ptr, "envInstallWebViewController");
    unsafe {
        crate::components::webview::waterui_env_install_webview_controller(
            env_ptr,
            super::webview_bridge::jni_create_webview,
        );
    }
}

/// Install view renderer in the environment.
#[unsafe(no_mangle)]
pub extern "system" fn Java_dev_waterui_android_ffi_WatcherJni_envInstallViewRenderer<'local>(
    _env: JNIEnv<'local>,
    _class: JClass<'local>,
    _env_ptr: jlong,
) {
    // Android does not currently support the cross-platform preview renderer.
    // (Preview rendering happens on the host via the desktop backends.)
}

/// Install window manager in the environment.
#[unsafe(no_mangle)]
pub extern "system" fn Java_dev_waterui_android_ffi_WatcherJni_envInstallWindowManager<'local>(
    _env: JNIEnv<'local>,
    _class: JClass<'local>,
    env_ptr: jlong,
) {
    let env_ptr = require_env_ptr(env_ptr, "envInstallWindowManager");
    unsafe {
        crate::window::waterui_env_install_window_manager(env_ptr, jni_window_show);
    }
}

// =============================================================================
// Environment service shims (Rust -> Java)
// =============================================================================

unsafe extern "C" fn jni_window_show(window: crate::window::WuiWindow) {
    let (background_tag, background_color_ptr) = match window.background {
        crate::window::WuiWindowBackground::Opaque => (0i32, 0i64),
        crate::window::WuiWindowBackground::Color { color } => (1i32, color as jlong),
    };

    super::with_jni_env(|env| {
        let class = env
            .find_class("dev/waterui/android/runtime/WindowManager")
            .expect("WindowManager class not found");
        env.call_static_method(
            class,
            "showWindow",
            "(JZZJJJIIJ)V",
            &[
                JValue::Long(window.title as jlong),
                JValue::Bool(if window.closable { 1 } else { 0 }),
                JValue::Bool(if window.resizable { 1 } else { 0 }),
                JValue::Long(window.content as jlong),
                JValue::Long(window.toolbar as jlong),
                JValue::Long(window.state as jlong),
                JValue::Int(window.style as jint),
                JValue::Int(background_tag as jint),
                JValue::Long(background_color_ptr),
            ],
        )
        .expect("WindowManager.showWindow JNI call failed");
    });
}
